function stat(p){return p.st?JSON.parse(p.st):{}}function stInc(p,k,n=1){const s=stat(p);s[k]=(s[k]||0)+n;p.st=JSON.stringify(s)}
function achVal(p,k){const s=stat(p),jb=p.jobs?JSON.parse(p.jobs):{};if(k==='lvl')return p.lvl;if(k==='streak')return p.streak;if(k==='decor')return JSON.parse(p.items).length;if(k==='earned')return p.xp;if(k==='rank')return Math.max(0,...Object.values(jb).map(rank));return s[k]||0}
function rate(p){let r=inc(p.lvl);r+=JSON.parse(p.items).length*5;r=Math.round(r*(1+(plvl(p.xp)-1)*0.03));if(p.boost>now())r*=2;if(p.life){const L=lifeOf(p);r=Math.round(r*moodK(L));if(L.pet&&L.pet.fd&&(Date.now()-new Date(L.pet.fd).getTime())<3*86400e3)r=Math.round(r*(1+0.02*L.pet.lvl));if(L.kn&&L.kn.tot)r=Math.round(r*(1+Math.min(20,Math.floor(L.kn.tot/5))/100));if(L.pair)r=Math.round(r*1.1)}return r}
